{!REQUIRESCRIPT("/soap/ajax/29.0/connection.js")}

var res = confirm('This will prepare the request to be sent again with the next batch of conversion uploads. Are you sure?');

if (res == true) {
  var dr = new sforce.SObject('DoubleClick_Request__c');
  dr.id = "{!DoubleClick_Request__c.Id}";
  dr.Conversion_Status__c = "New";
  dr.Request_Failed__c = false;
  dr.Error_Message__c = null;
  result = sforce.connection.update([dr]);
  location.reload(true);
}
